INSERT INTO wasichai.audit_log (id, organization_id, user_id, object_name, record_id, operation, before_state, after_state, occurred_at, document_id, reason, correlation_id, source) VALUES ('e1714260-396b-4267-8ac9-c49a0bed0ef6', '00000000-0000-0000-0000-000000000001', '00000000-0000-0000-0000-000000000100', 'admin:object', 'fc178f6c-6866-481d-87fb-0ddafc4a7467', 'CREATE', NULL, '{"name": "cuota_arbitrio", "label": "Cuota de arbitrio", "fields": [{"name": "anio", "type": "INTEGER", "label": "Año", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 0, "required": true, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": null, "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "periodo", "type": "INTEGER", "label": "Periodo", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 1, "required": true, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "El mes, de 1 a 12.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "monto", "type": "DECIMAL", "label": "Monto", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 2, "required": true, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "tasa_unitaria × cantidad_base × (1 + (H − P) × V) cuando el servicio reparte por habitantes, ya redondeado según REDONDEO_ARBITRIO; nunca negativo. Sin BASE_ARBITRIO, habitantes ni redondeo es la tasa mensual tal cual. Con tope de incremento (tope_aplicado), es monto_sin_tope reducido en proporción, nunca mayor.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "parametro_aplicado", "type": "TEXT", "label": "Parámetro aplicado", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 3, "required": true, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "Las llaves que se leyeron, separadas por ;: siempre TASA_ARBITRIO servicio:zona:uso, y BASE_ARBITRIO, HABITANTES_PROMEDIO, HABITANTES_VARIACION y REDONDEO_ARBITRIO cuando hubo filas, y TOPE_ARBITRIO cuando el tope se aplicó. Hasta 500 caracteres.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "zona", "type": "TEXT", "label": "Zona", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 4, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "La zona del predio ese mes, según la ordenanza.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "uso_arbitrio", "type": "TEXT", "label": "Uso de arbitrio", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 5, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "El uso de la secuencia ese mes, según la ordenanza.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "secuencia_uso", "type": "TEXT", "label": "Secuencia de uso", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 6, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "La secuencia de uso de la declaración (001, 002...): un PU por uso, como el SRTM. Vacía en las cuotas anteriores, que cuentan como la secuencia menor del predio.", "enumOptions": nul