ull, "relationTarget": null}, {"name": "habitantes_presuntos", "type": "BOOLEAN", "label": "Habitantes presuntos", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 11, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "Sí cuando la declaración no trae habitantes: se presume el promedio y el factor es 1.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "promedio_habitantes", "type": "DECIMAL", "label": "Promedio de habitantes", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 12, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "P: HABITANTES_PROMEDIO de servicio:zona:uso.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "variacion_habitante", "type": "DECIMAL", "label": "Variación por habitante", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 13, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "V: HABITANTES_VARIACION de servicio:zona:uso.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "influencia", "type": "TEXT", "label": "Influencia", "unique": false, "indexed": false, "visible": true, "editable": true, "position": 14, "required": false, "timeZone": null, "attributes": {"srid": null, "dimension": null, "geometry_type": null, "file_max_bytes": null, "file_content_types": null}, "description": "El nivel de influencia del predio, cuando la tasa del servicio lo usa.", "enumOptions": null, "defaultValue": null, "relationTarget": null}, {"name": "afluencia", "type": "TEXT", "label": "Afluencia", "unique": 